={
  "queries": [{
    "refId": "A",
    "datasource": { "uid": "{{ $env.GRAFANA_DATASOURCE_UID || 'YOUR_DATASOURCE_UID' }}" },
    "rawSql": "SELECT c.id AS cliente_id, c.nombre AS cliente_nombre, f.fecha_emision, f.monto, f.numero_factura FROM clientes c JOIN facturas f ON f.cliente_id = c.id WHERE f.fecha_emision >= NOW() - INTERVAL '12 months' ORDER BY c.id, f.fecha_emision",
    "format": "table"
  }],
  "from": "now-12M",
  "to": "now"
}

